/**
 * resolve_pr_branch.ts — the branch a `pr` run is working on, or nothing.
 *
 * A `pr` run checks the pull request out through `refs/pull/N/head`, which git
 * checks out DETACHED: the commit is the pull request's, and there is no local
 * branch. `commit_and_push` then has no refspec — `fatal: invalid refspec
 * '(HEAD detached at pull/802/head)'` — so the one agent whose job is to push a
 * fix is the one that cannot.
 *
 * The runner materialises the head branch as a local branch, and this is the
 * half that decides WHICH branch that is; the workflow step beside it does the
 * git work. A script because the decision is what can be wrong, and this way it
 * is testable without a runner.
 *
 * Prints the branch name on stdout, and nothing at all when there is no branch
 * to name. Diagnostics go to stderr, so stdout stays data a caller can consume
 * — the same split `resolve_orchestrator_parent.ts` uses. The script never exits
 * non-zero: a run that cannot name its branch stays on the detached head and
 * `resolveBranch()` then refuses with a message naming what the run cannot do.
 * Stopping before the agent has said anything would be worse than that.
 *
 * Three ways a name is refused, each for its own reason:
 *
 *   - the pull request is cross-repository. `headRefName` then names a branch in
 *     the FORK, and the base repository may well have one of the same name — a
 *     fork whose branch is called `main` would otherwise resolve to the default
 *     branch, and the run would push there.
 *   - it is not a branch name at all (empty, `HEAD`, a space, a control
 *     character). The caller splices the name into shell text and into
 *     `$GITHUB_ENV`, so `git check-ref-format --branch` is the boundary, and
 *     `HEAD` is among what it rejects.
 *   - the branch does not exist on `origin`. There is nothing to check out, and
 *     the caller must not invent one.
 *
 * Usage:
 *   resolve_pr_branch.ts --repo owner/name --number 12
 */
import { parseArgs } from "node:util";
import { gh, gitRun } from "../lib/gh.ts";
import { defineScript } from "./lib/script-ref.ts";

export interface ResolvePrBranchArgs {
  repo: string;
  number: string;
}

export const ref = defineScript<ResolvePrBranchArgs>(import.meta.url);

function log(message: string): void {
  console.error(`[atomaton-pr-branch] ${message}`);
}

/** What `gh pr view` says about the head of a pull request. */
export interface PrHead {
  branch: string;
  crossRepository: boolean;
}

/**
 * Read the head branch out of `gh pr view --json headRefName,isCrossRepository`.
 *
 * Anything unreadable answers "no branch" rather than throwing: this script's
 * whole contract is that it never fails the run it is deciding for. The fork
 * flag is carried separately from the name because the two refusals say
 * different things to whoever reads the log.
 */
export function prHead(prJson: string): PrHead {
  try {
    const pr = JSON.parse(prJson) as { headRefName?: unknown; isCrossRepository?: unknown };
    return {
      branch: typeof pr.headRefName === "string" ? pr.headRefName.trim() : "",
      crossRepository: pr.isCrossRepository === true,
    };
  } catch {
    return { branch: "", crossRepository: false };
  }
}

/**
 * Whether a name may be used as a branch, asked of git rather than pattern-matched.
 *
 * `check-ref-format --branch` is the same rule `git checkout` and `git push`
 * apply, so a name it accepts cannot be one of them refuses, and a name carrying
 * whitespace, a control character, `..`, `~`, `^`, `:` or a leading `-` is
 * rejected before it reaches a shell or the environment file. `HEAD` is rejected
 * by it too — it is not a branch, and it is what the step this replaces wrote.
 */
export function isBranchName(name: string): boolean {
  if (!name) return false;
  return gitRun("check-ref-format", "--branch", name).code === 0;
}

/**
 * Whether the branch is one this repository has, on the remote the run would push to.
 *
 * A pull request's `headRefName` exists in the head repository, which for a fork
 * is not `origin` — and the caller's fetch would fail, taking the step with it.
 * Asking first is what turns that into "stay detached".
 */
export function existsOnOrigin(name: string): boolean {
  const { code, stdout } = gitRun("ls-remote", "--heads", "origin", `refs/heads/${name}`);
  return code === 0 && stdout.trim() !== "";
}

function main(): void {
  const { values } = parseArgs({
    args: Bun.argv.slice(2),
    options: { repo: { type: "string" }, number: { type: "string" } },
  });

  const repo = (values.repo ?? "").trim();
  const number = Number((values.number ?? "").trim());
  if (!repo || !Number.isInteger(number) || number <= 0) {
    log("missing --repo or --number; this run has no branch to name");
    return;
  }

  const { code, stdout, stderr } = gh(
    "pr", "view", String(number), "--repo", repo,
    "--json", "headRefName,isCrossRepository",
  );
  if (code !== 0) {
    log(`could not read pull request #${number}: ${stderr || stdout}`);
    return;
  }

  const head = prHead(stdout);
  if (head.crossRepository) {
    log(`pull request #${number} is from a fork, so its head branch is not one this repository can push to`);
    return;
  }
  if (!head.branch) {
    log(`pull request #${number} names no head branch`);
    return;
  }
  if (!isBranchName(head.branch)) {
    log(`pull request #${number} names '${head.branch}', which is not a branch name`);
    return;
  }
  if (!existsOnOrigin(head.branch)) {
    log(`'${head.branch}' does not exist on origin; staying on the detached head`);
    return;
  }

  // The only thing on stdout, so a caller can consume it directly.
  console.log(head.branch);
}

if (import.meta.main) main();
