 * Whether a name may be used as a branch, asked of git rather than pattern-matched.
 *
 * `check-ref-format --branch` is the same rule `git checkout` and `git push`
 * apply, so a name it accepts cannot be one they refuse — and one it rejects
 * never reaches the shell that splices it into a fetch refspec or the
 * `$GITHUB_ENV` write that becomes `BRANCH`. That covers the empty name, `HEAD`
 * (not a branch, and exactly what the step this replaces used to write), names
 * carrying whitespace, control characters, `..`, `~`, `^`, `:`, `.lock`, and
 * anything starting with `-`.
 */
export function isBranchName(name: string): boolean {
  if (!name) return false;
  return gitRun("check-ref-format", "--branch", name).code === 0;
}

/**
 * Whether the branch is one `origin` has.
 *
 * A pull request's `headRefName` exists in its head repository, which for a fork
 * is not `origin`. Asking first turns "the fetch fails" into "this run stays
 * detached", and it is what stops a fork's branch being mistaken for a branch of
 * the same name in the base repository.
