2	/**
3	 * fake `gh` CLI, driven entirely by env vars so one fixture works for every
4	 * script under test. Shared by two consumers:
5	 *   - src/scripts/*.test.ts: its directory is prepended to PATH (as
6	 *     literally "gh") by testing/harness.ts's `runWithFakeGh`.
7	 *   - tests/e2e/*.e2e.test.ts: via tests/e2e/fake-gh.ts, prepended to PATH
8	 *     for the top-level `atoma` binary's own spawn env so every spawned MCP
9	 *     server (and every script THEY spawn in turn) resolves `gh` to this
10	 *     file instead of the real CLI.
11	 *
12	 *   FAKE_GH_RESPONSES = JSON array of { match: string[]; stdout?: string; code?: number }.
13	 *     A rule matches a real invocation when EVERY string in `match` is a
14	 *     substring of at least one argv element (order-independent, and works
15	 *     for combined tokens like "repos/owner/repo/issues/5"). The first
16	 *     matching rule (in array order) wins -- list more specific rules
17	 *     first when multiple calls could otherwise collide.
18	 *   FAKE_GH_LOG = path this appends one JSON line (the full argv array) to
19	 *     per invocation, so tests can assert on exact commands issued (e.g.
20	 *     the body of a posted comment), not just the script's own stdout.
21	 *
22	 * A rule may also carry `attempt: N`, meaning it applies only the Nth time a call
23	 * matching THAT rule is made -- not the Nth `gh` invocation overall. Counting per
24	 * rule rather than globally is what keeps such a test from breaking when unrelated
25	 * `gh` traffic appears before it. That is what makes a retry testable: attempt 1
26	 * returns the rate limit and the next returns the answer. The count comes from
27	 * FAKE_GH_LOG, so a test using `attempt` must set it -- each invocation is its own
28	 * process and the log is the only state they share.
29	 */
30	const args = process.argv.slice(2);
31	
32	const logPath = process.env.FAKE_GH_LOG;
33	let history: string[][] = [];
34	if (logPath) {
35	  const { appendFileSync, readFileSync } = await import("node:fs");
36	  appendFileSync(logPath, JSON.stringify(args) + "\n");
37	  // Every invocation so far, this one included -- so the first call sees length 1.
38	  history = readFileSync(logPath, "utf8")
39	    .split("\n")
40	    .filter(Boolean)
41	    .map((line) => JSON.parse(line) as string[]);
42	}
43	
44	interface Rule {
45	  match: string[];
46	  stdout?: string;
47	  code?: number;
48	  attempt?: number;
49	}
50	
51	const rules: Rule[] = process.env.FAKE_GH_RESPONSES ? JSON.parse(process.env.FAKE_GH_RESPONSES) : [];
52	
53	function argvMatches(rule: Rule, argv: string[]): boolean {
54	  return rule.match.every((needle) => argv.some((a) => a.includes(needle)));
55	}
56	
57	function matches(rule: Rule): boolean {
58	  if (!argvMatches(rule, args)) return false;
59	  if (rule.attempt === undefined) return true;
60	  return rule.attempt === history.filter((argv) => argvMatches(rule, argv)).length;
61	}
62	
63	const found = rules.find(matches);
64	if (found) {
65	  console.log(found.stdout ?? "");
66	  process.exit(found.code ?? 0);
