151	function splitConcatenatedJson(text: string): unknown[] {
152	  const results: unknown[] = [];
153	  let depth = 0;
154	  let start = -1;
155	  let inString = false;
156	  let escaped = false;
157	
158	  for (let i = 0; i < text.length; i++) {
159	    const c = text[i];
160	    if (inString) {
161	      if (escaped) escaped = false;
162	      else if (c === "\\") escaped = true;
163	      else if (c === '"') inString = false;
164	      continue;
165	    }
166	    if (c === '"') {
